/**
 * Trail of links from the root to the current page (`design/components/breadcrumbs.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/breadcrumbs.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Each,
  Icon,
  agentMember,
  agentPress,
  claimSlot,
  createDerived,
  elementRef,
  scope,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/breadcrumbs.module.css'
import Button from '../controls/Button'
import Menu from '../overlays/Menu'

export interface BreadcrumbItem {
  label: string
  href?: string
  onSelect?: () => void
}

export interface BreadcrumbsProps {
  /**
   * Opens the overflow on mount, for galleries and tests only.
   */
  defaultOpen?: boolean
  /**
   * The last item is the current page; its `href`/`onSelect` are ignored.
   */
  items: BreadcrumbItem[]
  /**
   * The landmark's accessible name, default `Breadcrumb`; localized hosts pass their own.
   */
  label?: string
  /**
   * Above this count, shows the first crumb, overflow and last two; `Infinity` disables it.
   */
  maxItems?: number
  /**
   * The app's router, for every crumb with an `href` (`link.md` §Routing): a click that would
   * navigate this tab, and a crumb chosen from the overflow, call it in place of the browser.
   */
  onNavigate?: (href: string) => void
  /**
   * The overflow control's accessible name, default `Show path`.
   */
  overflowLabel?: string
}

/** Trail of links from the root to the current page. */
export default function Breadcrumbs(given: BreadcrumbsProps): JSX.Element {
  const props = mergeProps(
    { maxItems: 4, label: 'Breadcrumb', overflowLabel: 'Show path' } as Defaults<
      BreadcrumbsProps,
      'maxItems' | 'label' | 'overflowLabel'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const root = elementRef<HTMLElement>()
    const collapsed = createDerived(() => props.items.length > props.maxItems)
    const row = createDerived(() =>
      collapsed.value
        ? [...props.items.slice(0, 1), null, ...props.items.slice(1).slice(-2)]
        : props.items,
    )
    const last = createDerived(() => row.value.length - 1)
    const hidden = createDerived(() =>
      collapsed.value
        ? props.items.slice(1, -2).map((item) => ({
            label: item.label,
            onSelect: () => {
              if (item.onSelect) item.onSelect()
              else if (item.href !== undefined) {
                if (props.onNavigate !== undefined) props.onNavigate?.(item.href)
                else window.location.assign(item.href)
              }
            },
          }))
        : [],
    )
    const navigatesHere = createDerived(
      () =>
        (event: MouseEvent): boolean =>
          !event.defaultPrevented &&
          event.button === 0 &&
          !event.metaKey &&
          !event.ctrlKey &&
          !event.shiftKey &&
          !event.altKey,
    )
    const route = createDerived(() => (event: MouseEvent, href: string | undefined): void => {
      if (href === undefined || !(props.onNavigate !== undefined) || !navigatesHere.value(event))
        return
      event.preventDefault()
      props.onNavigate?.(href)
    })
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'Breadcrumbs',
        element: () => root.value,
        state: () => ({
          items: props.items
            .filter(
              (item, at) => props.items.findIndex((other) => other.label === item.label) === at,
            )
            .map((item) => ({
              id: item.label,
              label: item.label,
              ...(item === props.items[props.items.length - 1] ||
              (item.href === undefined && item.onSelect === undefined)
                ? { disabled: true }
                : {}),
            })),
        }),
        actions: {
          choose: {
            argument: 'id',
            run: (value) =>
              (() => {
                const item = props.items.find((candidate) => candidate.label === value)
                if (item === undefined) return
                const shown = row.value.indexOf(item)
                if (shown === -1) hidden.value.find((entry) => entry.label === value)?.onSelect()
                else
                  agentPress(
                    root.value
                      ?.querySelectorAll(':scope > ol > li')
                      [shown]?.querySelector('a, button'),
                  )
              })(),
          },
        },
        withholds: () =>
          hidden.value.length === 0 ? null : root.value?.querySelectorAll(':scope > ol > li')[1],
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <nav class={styles.nav} aria-label={props.label} data-member="breadcrumbs" ref={root.attach}>
        {/* list */}
        <ol class={styles.list}>
          <Each
            of={row.value}
            by={(rung, at) => (rung === null ? 'overflow' : `${at}-${rung.label}`)}
            renew
          >
            {(rung, at) => (
              <li class={styles.item}>
                {rung === null ? (
                  <Menu
                    defaultOpen={props.defaultOpen}
                    items={hidden.value}
                    trigger={
                      <Button
                        variant="ghost"
                        tone="neutral"
                        size="sm"
                        iconOnly={true}
                        icon="overflow"
                        label={props.overflowLabel}
                      />
                    }
                  />
                ) : at() === last.value ? (
                  <span class={styles.crumb} aria-current="page">
                    {rung.label}
                  </span>
                ) : rung.href !== undefined ? (
                  <a
                    class={styles.crumb}
                    href={rung.href}
                    onclick={($event: MouseEvent) => (
                      rung.onSelect?.(),
                      route.value($event, rung.href)
                    )}
                  >
                    {rung.label}
                  </a>
                ) : rung.onSelect !== undefined ? (
                  <button class={styles.crumb} type="button" onclick={() => rung.onSelect?.()}>
                    {rung.label}
                  </button>
                ) : (
                  <span class={styles.crumb}>{rung.label}</span>
                )}
                {at() !== last.value ? (
                  <span class={styles.separator}>
                    <Icon name="next" size="sm" />
                  </span>
                ) : null}
              </li>
            )}
          </Each>
        </ol>
      </nav>
    )
  })
}
